export const BeerCanScene = forwardRef<THREE.Group, BeerCanSceneProps>(
  ({ texturePath }, ref) => {
    const { scene } = useGLTF('/beer2.gltf');
    const texture = useTexture(texturePath);

    useLayoutEffect(() => {
      // Apply texture to material
         if (obj.material) {
            obj.material.map = texture;
            obj.material.needsUpdate = true;
         }
    }, [scene, texture]);

    return <primitive object={scene} />;
  },
);
